__NUXT_JSONP__("/ch/feature", (function(a,b){return {data:[{details:{slug:"ch",pageTitle:"选择MLI的五大理由 | Mentor Language Institute",pageDescription:b,section1:{title:"选择MLI的五大理由",image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fmli-mentor.jpg"},section2:{title:"Mentor Language Institute 的五个特色",description:[b],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fsurvey.jpg",notes:"调查时间: 2017年1月至6月份，共342位学生。"},section3:[{title:"No.1 : 价格实惠",subtitle:"超值价格！每周仅 $209 起。下午课程比上午课程优惠 40%！",description:["学生选择MLI的主要的理由之一是价格实惠。","学生在我校上课的时间越长，学费将越优惠。若上课一个月(四周)，学费$1,220 \u003Cb\u003E=$305\u002F周\u003C\u002Fb\u003E. 若上课一年（48周），学费 10,032 \u003Cspan style=\"color: #ff0000; font-weight: bold;\"\u003E=$209\u002F周\u003C\u002Fspan\u003E."],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002FPRICE_CHART_WEB_JAN06.jpg",links:[{icon:a,text:"费用详细",link:"\u002Fch\u002Fprice"}]},{title:"No.2 : 优越的地理位置",subtitle:"Westwood & Hollywood : 洛杉矶的繁华区域",description:["Westwood和Hollywood都属于洛杉矶的黄金地段。学生前往 Santa Monica和洛杉矶 市区都很便利。"],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgreat-location.jpg",locations:[{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fwestwood-campus.jpg",label:"Westwood校区"},{image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fhollywood-campus.jpg",label:"Hollywood校区"}],links:[{icon:a,text:"Westwood校区详细内容",link:"\u002Fch\u002Fwestwood"},{icon:a,text:"Hollywood校区详细内容",link:"\u002Fch\u002Fhollywood"}]},{title:"No.3 : 丰富的课程",subtitle:"很多学生结束MLI课程之后，接着申请就读Santa Monica College，UCLA及其他学校。",description:["我们提供多类型的课程，比如TOEFL®, IELTS™。许多学生结束MLI语言课程之后，接着就读UCLA，USC或是Santa Monica College。"],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fgoing-to-college.jpg",links:[{icon:a,text:"MLI合作大学院校信息",link:"\u002Fch\u002Fgoing-to-college"}]},{title:"No.4 : 弹性的课程时间",subtitle:"我们提供早上，下午和晚上的课程。",description:["MLI提供三个时间段的课程。学生可选择早上，下午或是晚上的课程学习"],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fclass-schedule.png",notes:"这是Westwood校区的课程时间表。如果您需要 Hollywood 校区的时间表，请联系我们。"},{title:"No.5 : 住宿信息",subtitle:"我们的合作伙伴: US Support Services Inc. 为来自世界各地的学生提供住宿信息。",description:["我们的合作伙伴: US Support Services Inc. 负责寄宿家庭及宿舍的安排。他们提供学校附近40多个房间。很多第一次来美国的学生都会选择住在宿舍。"],image:"\u002Fimages\u002Fwhat-is-mli\u002Ffeature\u002Fdormitory.jpg",links:[{icon:a,text:"住宿详情",link:"\u002Fch\u002Fstay"}]}],dir:"\u002Ffeature",path:"\u002Ffeature\u002Fch",extension:".json",createdAt:"2026-10-22T16:31:29.177Z",updatedAt:"2026-03-24T13:34:16.360Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg","截至2017年，我校已帮助过17,000多位学生提高英语能力。洛杉矶有这么多的英语学校，为什么学生们选择我们呢? 以下是我们调查后得到的结果。")));